package com.logistics.gateway;
import org.springframework.context.annotation.*;import org.springframework.security.config.annotation.web.reactive.EnableWebFluxSecurity;import org.springframework.security.config.web.server.ServerHttpSecurity;import org.springframework.security.web.server.SecurityWebFilterChain;import org.springframework.web.cors.reactive.*;import org.springframework.web.cors.CorsConfiguration;import java.util.*;
@Configuration @EnableWebFluxSecurity public class GatewaySecurityConfig {@Bean SecurityWebFilterChain security(ServerHttpSecurity http){return http.csrf(ServerHttpSecurity.CsrfSpec::disable).authorizeExchange(a->a.anyExchange().permitAll()).build();}@Bean CorsWebFilter cors(){var c=new CorsConfiguration();c.setAllowedOrigins(List.of("http://localhost:5173"));c.setAllowedMethods(List.of("GET","POST","PUT","PATCH","DELETE","OPTIONS"));c.setAllowedHeaders(List.of("Authorization","Content-Type","Idempotency-Key"));var s=new UrlBasedCorsConfigurationSource();s.registerCorsConfiguration("/**",c);return new CorsWebFilter(s);}}
